import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.StopSound{SoundName: "record.pigstep", StopAll: false, StopMusicLegacy: true}
NAMED = bytes.fromhex("0e7265636f72642e706967737465700001")

# generated by gophertunnel b8bd735:
# &packet.StopSound{SoundName: "", StopAll: true, StopMusicLegacy: false}
EMPTY_NAME = bytes.fromhex("000100")

GOLDENS = [
    pytest.param(
        v2225.StopSoundPacket(name="record.pigstep", stop_all=False, stop_music_legacy=True), NAMED, id="named"
    ),
    pytest.param(v2225.StopSoundPacket(name="", stop_all=True, stop_music_legacy=False), EMPTY_NAME, id="empty-name"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_stop_sound_is_packet_87(version):
    assert version.PACKETS[87] is version.StopSoundPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_stop_sound_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_stop_sound_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_sound_name_length_prefix_is_a_varint():
    packet = v2225.StopSoundPacket(name="a" * 200, stop_all=True, stop_music_legacy=True)
    wire = bytes(packet)
    assert len(wire) == 204
    assert v2225.StopSoundPacket.from_bytes(wire) == packet
